USE appointment_db; INSERT IGNORE INTO time_slots(doctor_id,slot_date,start_time,end_time,available) WITH RECURSIVE d AS(SELECT CURDATE() x UNION ALL SELECT DATE_ADD(x,INTERVAL 1 DAY) FROM d WHERE x<DATE_ADD(CURDATE(),INTERVAL 20 DAY)) SELECT 1,x,'09:00:00','09:30:00',TRUE FROM d UNION ALL SELECT 1,x,'10:00:00','10:30:00',TRUE FROM d UNION ALL SELECT 1,x,'11:00:00','11:30:00',TRUE FROM d UNION ALL SELECT 1,x,'14:00:00','14:30:00',TRUE FROM d UNION ALL SELECT 1,x,'15:00:00','15:30:00',TRUE FROM d;
